select r.as_of_date, to_char(r.created_at,'MM-DD HH24:MI') c, left(r.git_sha,10) sha, r.metrics->'execution_scope'->>'mode' m, r.metrics->'input_provenance' prov, (select count(*) from player_forecast_source_observations o where o.provider='forge' and o.dataset_key='forge-run-inputs-v1' and o.entity_key=r.run_id::text) snaps from forge_runs r where r.created_at >= '2026-11-09' order by r.created_at
